// Every error response has the shape { error: { code, message } }. Messages sent to clients are
// written here on purpose; anything else is logged server-side and replaced with a generic message.

export class ApiError extends Error {
  constructor(status, code, message) {
    super(message)
    this.name = 'ApiError'
    this.status = status
    this.code = code
  }
}

export function sendError(res, status, code, message) {
  res.status(status).json({ error: { code, message } })
}

// Returns the ApiError to send for a known client-side failure, or null for anything unexpected.
function toClientError(err) {
  if (err instanceof ApiError) return err
  // body-parser errors (express.json) carry a `type` we can map precisely.
  if (err?.type === 'entity.parse.failed') {
    return new ApiError(400, 'invalid_json', 'Request body is not valid JSON')
  }
  if (err?.type === 'entity.too.large') {
    return new ApiError(413, 'payload_too_large', 'Request body is too large')
  }
  return null
}

export function notFoundHandler(req, res) {
  sendError(res, 404, 'not_found', 'Route not found')
}

// Must be registered last and keep all four parameters, or Express will not treat it as an error handler.
export function errorHandler(err, req, res, next) {
  if (res.headersSent) return next(err)

  const clientError = toClientError(err)
  if (clientError) {
    return sendError(res, clientError.status, clientError.code, clientError.message)
  }

  console.error(err)
  sendError(res, 500, 'internal_error', 'An unexpected error occurred')
}

