import express from 'express'
import { createOrdersRepo, OrderNotFoundError, OrderStateError } from './orders-repo.mjs'
import { ApiError, errorHandler, notFoundHandler } from './errors.mjs'

function validateOrderInput(body) {
  const { sku, quantity } = body ?? {}
  if (
    typeof sku !== 'string' ||
    sku.trim() === '' ||
    !Number.isInteger(quantity) ||
    quantity < 1 ||
    quantity > 100
  ) {
    throw new ApiError(
      400,
      'validation_failed',
      'sku must be a non-empty string and quantity an integer from 1 to 100',
    )
  }
  return { sku, quantity }
}

export function createApp({ repo = createOrdersRepo() } = {}) {
  const app = express()
  app.disable('x-powered-by')
  app.use(express.json({ limit: '10kb' }))

  app.get('/api/health', (req, res) => {
    res.json({ ok: true })
  })

  app.get('/api/orders', async (req, res) => {
    res.json({ orders: await repo.list() })
  })

  app.get('/api/orders/:id', async (req, res) => {
    const order = await repo.get(req.params.id)
    if (!order) throw new ApiError(404, 'not_found', 'Order not found')
    res.json(order)
  })

  app.post('/api/orders', async (req, res) => {
    const input = validateOrderInput(req.body)
    const order = await repo.create(input)
    res.status(201).json(order)
  })

  app.post('/api/orders/:id/cancel', async (req, res) => {
    try {
      res.json(await repo.cancel(req.params.id))
    } catch (err) {
      if (err instanceof OrderNotFoundError) {
        throw new ApiError(404, 'not_found', 'Order not found')
      }
      if (err instanceof OrderStateError) {
        throw new ApiError(409, 'conflict', `Order is ${err.orderStatus} and can no longer be cancelled`)
      }
      throw err
    }
  })

  app.use(notFoundHandler)
  app.use(errorHandler)

  return app
}

